#include <DHT.h>

// Define DHT sensor pin
#define DHTPIN 2
#define DHTTYPE DHT22

// Create an instance of the DHT sensor
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
}

void loop() {
  // Start the DHT sensor
  dht.begin();

  // Check if any reads failed and exit early (to try again next time)
  if (!dht.update()) {
    Serial.println("Failed to read from DHT sensor!");
    return;
  }

  // Read temperature and humidity values
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Print to serial monitor
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.println(" *C");
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println(" %");

  // Wait 2 seconds before taking the next reading
  delay(2000);
}
```

**Note**: This code is for calibration purposes only. It will continuously read the temperature and humidity values from the DHT22 sensor and print them to the serial monitor. To calibrate the sensor, you need to manually measure the temperature and humidity at the same time and compare them with the readings from the code.

